{
  "microservices": [
    {
      "microservice_name": "Master Data Administration Service",
      "responsibility": "Maintains shared supporting master data (departments, contract types, user categories, organization/interaction types, tax reasons, billing schemes, frequencies) and per-user application settings used across other areas.",
      "communicates_with": [
        "People and HR Service",
        "CRM and Proposals Service",
        "Time and Activity Service",
        "Finance and Billing Service"
      ]
    },
    {
      "microservice_name": "People and HR Service",
      "responsibility": "Registers and maintains users with personal and contractual data, department, category, access profile, employment agreements, and password administration.",
      "communicates_with": [
        "Master Data Administration Service",
        "Vacation Management Service",
        "Security and Access Control Service",
        "Notification Service",
        "Document Management Service"
      ]
    },
    {
      "microservice_name": "Vacation Management Service",
      "responsibility": "Records vacation requests, manages their pending/accepted/rejected/cancelled lifecycle, calculates balances and prorated entitlements over business days, and requests approver notifications.",
      "communicates_with": [
        "People and HR Service",
        "Notification Service"
      ]
    },
    {
      "microservice_name": "CRM and Proposals Service",
      "responsibility": "Maintains organizations, contacts, external collaborators, job roles, and interactions; manages proposals through their lifecycle and converts billable items into billing drafts.",
      "communicates_with": [
        "Master Data Administration Service",
        "Finance and Billing Service",
        "Time and Activity Service"
      ]
    },
    {
      "microservice_name": "Time and Activity Service",
      "responsibility": "Manages projects, activities, roles, objectives and work allocations; classifies billable/non-billable and counting time, computes worked hours, and enforces evidence policies.",
      "communicates_with": [
        "Master Data Administration Service",
        "CRM and Proposals Service",
        "Finance and Billing Service",
        "Notification Service"
      ]
    },
    {
      "microservice_name": "Finance and Billing Service",
      "responsibility": "Manages accounts, transactions, receivables/payables, billing records with items, taxes, due dates, payment state, and credit instruments, including automatic financial calculations.",
      "communicates_with": [
        "Master Data Administration Service",
        "CRM and Proposals Service",
        "Time and Activity Service"
      ]
    },
    {
      "microservice_name": "Document Management Service",
      "responsibility": "Organizes versioned documents by category, associates them with people and areas, and maintains knowledge base publications and notice boards.",
      "communicates_with": [
        "People and HR Service"
      ]
    },
    {
      "microservice_name": "Orders and Commissions Service",
      "responsibility": "Records orders and commissions linked to projects and collaborators, controls their workflow states, preserves change history, and sends related documents.",
      "communicates_with": [
        "Time and Activity Service",
        "Notification Service"
      ]
    },
    {
      "microservice_name": "Reporting Service",
      "responsibility": "Generates domain reports (billing, hours, projects, proposals, interactions, organizations, commissions) and exports them in CSV, PDF, HTML, RTF, XLS, and ODT formats.",
      "communicates_with": [
        "Finance and Billing Service",
        "Time and Activity Service",
        "CRM and Proposals Service"
      ]
    },
    {
      "microservice_name": "Security and Access Control Service",
      "responsibility": "Controls access by user profile and scope of responsibility, supports local and LDAP authentication, and applies access control to critical entities.",
      "communicates_with": [
        "People and HR Service"
      ]
    },
    {
      "microservice_name": "Notification Service",
      "responsibility": "Sends email notifications for relevant business events such as vacation requests, contract expiry, pending evidence, and orders.",
      "communicates_with": [
        "Vacation Management Service",
        "People and HR Service",
        "Time and Activity Service",
        "Orders and Commissions Service"
      ]
    }
  ]
}

